    let dIdx = 0;
    while (currentX < CANVAS_WIDTH) {
        const threads = safePlan[dIdx % safePlan.length];
        if (threads === 0) currentX += dentWidthPx;
        else {
            const w = dentWidthPx / threads;
            for (let k = 0; k < threads; k++) {
                warpPositions.push({ x: currentX, w, jitter: (Math.random() - 0.5) * (w * 0.05) });
                currentX += w;
            }
