            if (waDef?.isExtraWarp) { if (!wTop) waOp = hideFloats ? 0 : (waDef.extraFloatOpacity ?? 0.08); else waOv = waDef.extraOverlap ?? 0; }

            if (wTop) { 
                if (wTex && wOp > 0) drawThread(wTex, gX, gY, gW, gH, wDef?.thickness || 1, wDef?.spacing || 0, false, r, c, wOp, wOv, wDef?.floatWaviness, 0, 0, jit); 
            } else { 
                if (waTex && waOp > 0) drawThread(waTex, gX, gY, gW, gH, waDef?.thickness || 1, waDef?.spacing || 0, true, r, c, waOp, waOv, waDef?.floatWaviness, 0, 0, jit); 
            }
        }
    }

    // PASS 2: SHADOWS
    for (let r = 0; r < rCount; r++) {
        const pR = r % rows, gY = rowY[r], gH = rowHeights[r];
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols, waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A', waDef = warpYarns[waYId], wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A', wDef = weftYarns[wYId], gX = warpPositions[c].x, gW = warpPositions[c].w;
            const wTopR = (structure[pR] && structure[pR][pC]) || false;
            const wTop = viewSide === 'face' ? wTopR : !wTopR;

            const tD = wTop ? waDef : wDef;
            let tOp = 1.0;
            if (wTop && waDef?.isExtraWarp) tOp = hideFloats ? 0 : (waDef.extraFloatOpacity ?? 0.08);
            if (!wTop && wDef?.isExtraWeft) tOp = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08);

            const sTh = (tD?.shadowThrow ?? 1.0) * SS_FACTOR * (dpi/96), sAn = (tD?.shadowAngle ?? 135) * Math.PI/180;
            if (tOp > 0.1 && sTh > 0) {
                const sW = wTop ? NOMINAL_WARP_W * (tD?.thickness || 1) * 1.1 : gW * 1.1, sH = wTop ? gH * 1.1 : NOMINAL_WEFT_H * (tD?.thickness || 1) * 1.1;
                const sX = (gX + gW/2 - sW/2) + Math.cos(sAn)*sTh, sY = (gY + gH/2 - sH/2) + Math.sin(sAn)*sTh;
                ctx.globalAlpha = 0.4; ctx.drawImage(shadowCanvas, sX - sW*0.1, sY - sH*0.1, sW*1.2, sH*1.2); ctx.globalAlpha = 1.0;
            }
        }
    }

    // PASS 3: TOP YARNS
    for (let r = 0; r < rCount; r++) {
        const pR = r % rows, wYId = weftYarnSequence[pR % weftYarnSequence.length] || 'A', wDef = weftYarns[wYId], wTex = textureMap.get(`weft-${wYId}`), gY = rowY[r], gH = rowHeights[r];
        for (let c = 0; c < totalCols; c++) {
            const pC = c % cols, waYId = warpYarnSequence[pC % warpYarnSequence.length] || 'A', waDef = warpYarns[waYId], waTex = textureMap.get(`warp-${waYId}`), gX = warpPositions[c].x, gW = warpPositions[c].w, jit = warpPositions[c].jitter;
            const wTopR = (structure[pR] && structure[pR][pC]) || false;
            const wTop = viewSide === 'face' ? wTopR : !wTopR;

            const pWT = viewSide === 'face' ? ((structure[pR] && structure[pR][(pC - 1 + cols) % cols]) || false) : !((structure[pR] && structure[pR][(pC - 1 + cols) % cols]) || false);
            const nWT = viewSide === 'face' ? ((structure[pR] && structure[pR][(pC + 1) % cols]) || false) : !((structure[pR] && structure[pR][(pC + 1) % cols]) || false);
            const uWT = viewSide === 'face' ? ((structure[(pR - 1 + rows) % rows] && structure[(pR - 1 + rows) % rows][pC]) || false) : !((structure[(pR - 1 + rows) % rows] && structure[(pR - 1 + rows) % rows][pC]) || false);
            const dWT = viewSide === 'face' ? ((structure[(pR + 1) % rows] && structure[(pR + 1) % rows][pC]) || false) : !((structure[(pR + 1) % rows] && structure[(pR + 1) % rows][pC]) || false);

            let wAO = 0, waAO = 0, wT = 0, waT = 0;
            if (!wTop && (pWT || nWT)) { wAO = wDef?.bindingDepth || 0.4; wT = wDef?.floatTaper || 0; }
            if (wTop && (!uWT || !dWT)) { waAO = waDef?.bindingDepth || 0.4; waT = waDef?.floatTaper || 0; }

            let wOp = 1.0, wOv = 0.0, waOp = 1.0, waOv = 0.0;
            if (wDef?.isExtraWeft) { if (wTop) wOp = hideFloats ? 0 : (wDef.extraFloatOpacity ?? 0.08); else wOv = wDef.extraOverlap ?? 0; }
            if (waDef?.isExtraWarp) { if (!wTop) waOp = hideFloats ? 0 : (waDef.extraFloatOpacity ?? 0.08); else waOv = waDef.extraOverlap ?? 0; }

            if (wTop) { 
                if (waTex && waOp > 0) drawThread(waTex, gX, gY, gW, gH, waDef?.thickness || 1, waDef?.spacing || 0, true, r, c, waOp, waOv, waDef?.floatWaviness, waAO, waT, jit); 
            } else { 
                if (wTex && wOp > 0) drawThread(wTex, gX, gY, gW, gH, wDef?.thickness || 1, wDef?.spacing || 0, false, r, c, wOp, wOv, wDef?.floatWaviness, wAO, wT, jit); 
            }
        }
    }

    if (SS_FACTOR > 1.0) {
        const finalCanvas = document.createElement('canvas');
        finalCanvas.width = Math.round(PHYSICAL_WIDTH_INCH * dpi);
        finalCanvas.height = Math.round(PHYSICAL_HEIGHT_INCH * dpi);
        const finalCtx = finalCanvas.getContext('2d');
        if (finalCtx) {
            if (smoothingQuality === 'none') { finalCtx.imageSmoothingEnabled = false; } 
            else { finalCtx.imageSmoothingEnabled = true; finalCtx.imageSmoothingQuality = 'high'; }
            finalCtx.drawImage(canvas, 0, 0, finalCanvas.width, finalCanvas.height);
            return finalCanvas;
        }
    }
    return canvas;
};

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { YarnDefinition, YarnModel, YarnCountSystem, FiberType, YarnConstruction } from '../types';
import { generateYarnTexture } from '../services/yarnRenderer';

const Slider: React.FC<{
    label: string; 
    value: number; 
    onChange: (value: number) => void; 
    min: number; 
    max: number; 
    step: number; 
    subLabel?: string;
}> = ({ label, value, onChange, min, max, step, subLabel }) => (
    <div>
        <div className="flex justify-between text-[10px] font-bold text-gray-500 uppercase mb-1">
            <span>{label}</span>
            <span className="text-gray-300">{typeof value === 'number' ? value.toFixed(2) : value} {subLabel}</span>
        </div>
        <input 
            type="range" 
            min={min} 
            max={max} 
            step={step} 
            value={value || 0} 
            onChange={e => onChange(parseFloat(e.target.value))} 
            className="w-full h-1 bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-600" 
        />
    </div>
